import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, ventana, Easing, interpolate, clamp, Destello, Ondas} from './kit';
const mono = (t: number[]) => t.reduce<number[]>((a, x) => { a.push(a.length ? Math.max(x, a[a.length - 1] + 0.01) : x); return a; }, []);
const lerp = (s: number, t: number[], v: number[]) => interpolate(s, mono(t), v, {...clamp, easing: Easing.inOut(Easing.cubic)});
const ap = (s: number, t0: number, d = 0.7) => interpolate(s, [t0, t0 + d], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
const cam = (s: number, p: number[][]) => {
const ts = p.map((q) => q[0]);
const v = (k: number) => (p.length === 1 ? p[0][k] : lerp(s, ts, p.map((q) => q[k])));
const z = v(3);
return `translate(540 1040) scale(${z}) translate(${-v(1)} ${-v(2)})`;
};
const mix = (a: string, b: string, k: number) => {
const pa = [1, 3, 5].map((i) => parseInt(a.slice(i, i + 2), 16));
const pb = [1, 3, 5].map((i) => parseInt(b.slice(i, i + 2), 16));
const q = Math.max(0, Math.min(1, k));
return `rgb(${pa.map((x, i) => Math.round(x + (pb[i] - x) * q)).join(',')})`;
};
const rad = (a: number) => (a * Math.PI) / 180;
const SOMBRA = '#1d1530';

const Sitio: React.FC<{s: number; t0: number; t1: number; children: React.ReactNode}> = ({s, t0, t1, children}) => {
const o = ventana(s, t0, t1, 0.6);
if (o <= 0) return null;
return <g opacity={o}>{children}</g>;
};

type Look = {piel: string; ropa: string; ropa2: string; pelo: string; pant?: string; peinado?: string; barba?: string; corona?: boolean; lentes?: boolean; tunica?: boolean; alas?: boolean; delantal?: boolean};
type Pose = {bi?: number; bd?: number; cab?: number; rod?: number; sen?: number; boca?: number; llora?: number; cierra?: number; paso?: number; habla?: number};

const Cuerpo: React.FC<{L: Look; P: Pose; s: number; sil?: string}> = ({L, P, s, sil}) => {
const c = (x: string) => sil || x;
const k = P.rod || 0;
const sen = P.sen || 0;
const hipY = sen > 0 ? -235 : -265 + 125 * k;
const res = Math.sin(s * 2.1) * 3;
const sh = hipY - 185 + res;
const pz = P.paso ? Math.sin(s * 5.5) * 38 * P.paso : 0;
const piernas = [-1, 1].map((sd) => {
const hx = sd * 30;
const kn = sen > 0 ? [hx + 125, hipY - 4] : [hx + 55 * k + sd * 4 + sd * pz * 0.5, -135 * (1 - k) - 35 * k];
const ft = sen > 0 ? [hx + 128, -12] : [hx - 85 * k + sd * 6 + sd * pz, -12];
return {hx, kn, ft};
});
const low = L.tunica ? (sen > 0 ? hipY + 30 : Math.min(-25, hipY + 235)) : hipY + 10;
const brazo = (sd: number, a: number) => {
const sx = sd * 64, sy = sh + 22;
const ex = sx + sd * Math.sin(rad(a)) * 118, ey = sy + Math.cos(rad(a)) * 118;
const b = a + 28;
return {sx, sy, ex, ey, hx: ex + sd * Math.sin(rad(b)) * 112, hy: ey + Math.cos(rad(b)) * 112};
};
const A = brazo(-1, P.bi ?? 12), B = brazo(1, P.bd ?? 12);
const hy = sh - 100;
const parp = s % 3.7 < 0.13 ? 0.15 : 1;
const boca = P.boca ?? 0.5;
const pelo = (
L.peinado === 'velo' ? <path d={`M-68 ${hy + 12} Q-72 ${hy - 88} 0 ${hy - 86} Q72 ${hy - 88} 68 ${hy + 12} Q58 ${hy - 50} 0 ${hy - 52} Q-58 ${hy - 50} -68 ${hy + 12}Z`} fill={c(L.ropa2)} />
: L.peinado === 'canoso' ? <g><ellipse cx={-54} cy={hy - 6} rx={14} ry={28} fill={c(L.pelo)} /><ellipse cx={54} cy={hy - 6} rx={14} ry={28} fill={c(L.pelo)} /><path d={`M-40 ${hy - 56} Q0 ${hy - 76} 40 ${hy - 56}`} stroke={c(L.pelo)} strokeWidth={10} fill="none" strokeLinecap="round" /></g>
: L.peinado === 'rizo' ? <g>{[-48, -24, 0, 24, 48].map((x, i) => <circle key={i} cx={x} cy={hy - 58 + Math.abs(x) * 0.5} r={24} fill={c(L.pelo)} />)}</g>
: <g><path d={`M-62 ${hy - 4} Q-66 ${hy - 82} 0 ${hy - 78} Q66 ${hy - 82} 62 ${hy - 4} Q50 ${hy - 50} 0 ${hy - 48} Q-48 ${hy - 50} -62 ${hy - 4}Z`} fill={c(L.pelo)} />{L.peinado === 'moño' && <circle cx={10} cy={hy - 82} r={28} fill={c(L.pelo)} />}</g>
);
return (
<g>
{L.alas && [-1, 1].map((sd) => <path key={sd} transform={`translate(${sd * 30} ${sh + 40}) rotate(${sd * (14 + 7 * Math.sin(s * 1.6))})`} d={`M0 0 Q${sd * 200} -230 ${sd * 330} -130 Q${sd * 270} 10 ${sd * 300} 120 Q${sd * 170} 90 0 60Z`} fill={c('#fff6e2')} />)}
{L.peinado === 'largo' && <ellipse cx={0} cy={hy + 40} rx={76} ry={118} fill={c(L.pelo)} />}
{L.peinado === 'velo' && <path d={`M-94 ${hy + 200} Q-112 ${hy - 92} 0 ${hy - 94} Q112 ${hy - 92} 94 ${hy + 200}Z`} fill={c(L.ropa2)} />}
{piernas.map((p) => (
<g key={p.hx}>
<path d={`M${p.hx} ${hipY} L${p.kn[0]} ${p.kn[1]} L${p.ft[0]} ${p.ft[1]}`} stroke={c(L.pant || L.ropa)} strokeWidth={50} strokeLinecap="round" strokeLinejoin="round" fill="none" />
<ellipse cx={p.ft[0] + (sen > 0 ? 18 : 0)} cy={-8} rx={40} ry={17} fill={c('#2a2230')} />
</g>
))}
<path d={`M-80 ${low} Q-92 ${sh + 40} -62 ${sh} Q0 ${sh - 30} 62 ${sh} Q92 ${sh + 40} 80 ${low}Z`} fill={c(L.ropa)} />
{L.delantal && <path d={`M-50 ${sh + 80} L50 ${sh + 80} L60 ${low - 6} L-60 ${low - 6}Z`} fill={c(L.ropa2)} />}
{!L.delantal && !L.tunica && <rect x={-80} y={hipY - 26} width={160} height={22} rx={8} fill={c(L.ropa2)} />}
{L.tunica && <path d={`M-76 ${hipY - 40} Q0 ${hipY - 20} 76 ${hipY - 40} L76 ${hipY - 14} Q0 ${hipY + 6} -76 ${hipY - 14}Z`} fill={c(L.ropa2)} />}
{!sil && <path d={`M-30 ${sh + 40} V${low - 30} M30 ${sh + 40} V${low - 30}`} stroke="#000" strokeOpacity={0.1} strokeWidth={4} />}
{[A, B].map((q, i) => (
<g key={i}>
<path d={`M${q.sx} ${q.sy} L${q.ex} ${q.ey} L${q.hx} ${q.hy}`} stroke={c(L.ropa)} strokeWidth={40} strokeLinecap="round" strokeLinejoin="round" fill="none" />
<circle cx={q.hx} cy={q.hy} r={23} fill={c(L.piel)} />
</g>
))}
<rect x={-20} y={sh - 50} width={40} height={56} rx={14} fill={c(L.piel)} />
<g transform={`rotate(${P.cab || 0} 0 ${sh - 30})`}>
{[-1, 1].map((sd) => <ellipse key={sd} cx={sd * 58} cy={hy + 6} rx={11} ry={17} fill={c(L.piel)} />)}
<ellipse cx={0} cy={hy} rx={58} ry={66} fill={c(L.piel)} />
{L.barba && <path d={`M-52 ${hy + 6} Q-48 ${hy + 88} 0 ${hy + 94} Q48 ${hy + 88} 52 ${hy + 6} Q30 ${hy + 40} 0 ${hy + 42} Q-30 ${hy + 40} -52 ${hy + 6}Z`} fill={c(L.barba)} />}
{pelo}
{L.corona && <path d={`M-44 ${hy - 60} L-46 ${hy - 104} L-22 ${hy - 82} L0 ${hy - 114} L22 ${hy - 82} L46 ${hy - 104} L44 ${hy - 60}Z`} fill={c('#f2c14e')} />}
{!sil && (
<g>
{[-1, 1].map((sd) => (
<g key={sd}>
{(P.cierra || 0) > 0.5
? <path d={`M${sd * 22 - 10} ${hy - 2} Q${sd * 22} ${hy + 6} ${sd * 22 + 10} ${hy - 2}`} stroke="#15110f" strokeWidth={4} fill="none" strokeLinecap="round" />
: <g><ellipse cx={sd * 22} cy={hy - 4} rx={8} ry={8 * parp} fill="#15110f" />{parp > 0.5 && <circle cx={sd * 22 + 2.5} cy={hy - 7} r={2.8} fill="#fff" />}</g>}
<path d={`M${sd * 9} ${hy - 29} Q${sd * 22} ${hy - 31} ${sd * 34} ${hy - 23}`} stroke="#2a1d18" strokeOpacity={0.7} strokeWidth={4} fill="none" strokeLinecap="round" />
<ellipse cx={sd * 33} cy={hy + 20} rx={12} ry={7} fill="#ff8a8a" opacity={0.3} />
{(P.llora || 0) > 0 && <circle cx={sd * 26} cy={hy + 8 + ((s * 55 + (sd > 0 ? 30 : 0)) % 70)} r={5} fill="#bfe3ff" opacity={P.llora} />}
{L.lentes && <circle cx={sd * 22} cy={hy - 4} r={17} stroke="#4a4038" strokeWidth={3.5} fill="none" />}
</g>
))}
<path d={`M2 ${hy + 8} Q9 ${hy + 20} 0 ${hy + 24}`} stroke="#000" strokeOpacity={0.25} strokeWidth={4} fill="none" strokeLinecap="round" />
{P.habla ? <ellipse cx={0} cy={hy + 42} rx={10} ry={3 + 5 * Math.abs(Math.sin(s * 11))} fill="#5a2f26" />
: <path d={`M-16 ${hy + 40} Q0 ${hy + 40 + 14 * boca} 16 ${hy + 40}`} stroke="#5a2f26" strokeWidth={5} fill="none" strokeLinecap="round" />}
</g>
)}
</g>
</g>
);
};

const Figura: React.FC<{id: string; x: number; y: number; e: number; L: Look; P: Pose; s: number; luz?: string; flip?: boolean; o?: number}> = ({id, x, y, e, L, P, s, luz = '#ffe0a8', flip, o = 1}) => (
<g transform={`translate(${x} ${y}) scale(${flip ? -e : e} ${e})`} opacity={o}>
<ellipse cx={0} cy={-330} rx={330} ry={420} fill={`url(#halo-${id})`} />
<ellipse cx={0} cy={0} rx={230} ry={30} fill={SOMBRA} opacity={0.35} />
<g transform="translate(-7 -5)" opacity={0.85}><Cuerpo L={L} P={P} s={s} sil={luz} /></g>
<Cuerpo L={L} P={P} s={s} />
<g mask={`url(#m-${id})`} opacity={0.4}><Cuerpo L={L} P={P} s={s} sil={SOMBRA} /></g>
<defs>
<radialGradient id={`halo-${id}`}><stop offset={0} stopColor={luz} stopOpacity={0.38} /><stop offset={1} stopColor={luz} stopOpacity={0} /></radialGradient>
<linearGradient id={`g-${id}`} x1={-300} y1={0} x2={300} y2={0} gradientUnits="userSpaceOnUse"><stop offset={0.45} stopColor="#000" /><stop offset={0.72} stopColor="#fff" /></linearGradient>
<mask id={`m-${id}`} maskUnits="userSpaceOnUse" x={-700} y={-950} width={1400} height={1050}><rect x={-700} y={-950} width={1400} height={1050} fill={`url(#g-${id})`} /></mask>
</defs>
</g>
);

const Polvo: React.FC<{s: number; color?: string; n?: number; y0?: number; y1?: number}> = ({s, color = '#ffe6a8', n = 26, y0 = 450, y1 = 1850}) => (
<g>
{Array.from({length: n}, (_, i) => {
const h = y1 - y0;
const x = (((i * 157 + Math.sin(s * 0.4 + i) * 40) % 1080) + 1080) % 1080;
const y = y0 + ((((i * 263) - s * (14 + (i % 5) * 5)) % h) + h) % h;
return <circle key={i} cx={x} cy={y} r={2 + (i % 3) * 1.5} fill={color} opacity={0.25 + 0.35 * Math.abs(Math.sin(s * 0.9 + i))} />;
})}
</g>
);

const Rayos: React.FC<{s: number; x: number; y: number; color?: string; k?: number; n?: number}> = ({s, x, y, color = '#ffe2a0', k = 1, n = 7}) => (
<g opacity={0.55 * k}>
{Array.from({length: n}, (_, i) => {
const a = rad(-55 + i * (110 / (n - 1)) + Math.sin(s * 0.3 + i) * 4);
const ex = x + Math.sin(a) * 1600, ey = y + Math.cos(a) * 1600;
return <path key={i} d={`M${x} ${y} L${ex - 70} ${ey} L${ex + 70} ${ey}Z`} fill={color} opacity={0.16 + 0.1 * Math.sin(s * 0.7 + i * 1.3)} />;
})}
</g>
);

const Paloma: React.FC<{s: number; t0: number; dur?: number; y?: number; dir?: number; e?: number}> = ({s, t0, dur = 5, y = 700, dir = 1, e = 1}) => {
const k = (s - t0) / dur;
if (k < 0 || k > 1) return null;
const x = dir > 0 ? -120 + k * 1340 : 1200 - k * 1340;
const f = Math.sin(s * 9);
return (
<g transform={`translate(${x} ${y + Math.sin(k * 6) * 40 - k * 120}) scale(${e * dir} ${e})`}>
<ellipse cx={0} cy={0} rx={40} ry={17} fill="#fbf7ef" />
<circle cx={36} cy={-9} r={13} fill="#fbf7ef" />
<path d="M47 -9 L60 -5 L47 -2Z" fill="#e8a64a" />
<circle cx={39} cy={-12} r={2.6} fill="#15110f" />
<path d={`M-6 -6 Q-12 ${-64 * f} -50 ${-74 * f} Q-22 ${-30 * f} 12 -4Z`} fill="#ffffff" />
<path d="M-38 -2 L-66 -14 L-64 10Z" fill="#efe9dd" />
</g>
);
};

const Vela: React.FC<{s: number; x: number; y: number; e?: number}> = ({s, x, y, e = 1}) => {
const f = 1 + 0.12 * Math.sin(s * 6) + 0.06 * Math.sin(s * 13);
return (
<g transform={`translate(${x} ${y}) scale(${e})`}>
<circle cx={0} cy={-70} r={95 * f} fill="#ffcf7a" opacity={0.18} />
<rect x={-16} y={-50} width={32} height={60} rx={6} fill="#f3e6cf" />
<path d={`M0 ${-50 - 46 * f} Q15 -62 0 -50 Q-15 -62 0 ${-50 - 46 * f}Z`} fill="#ffb347" />
<path d={`M0 ${-50 - 28 * f} Q6 -58 0 -52 Q-6 -58 0 ${-50 - 28 * f}Z`} fill="#fff3c4" />
</g>
);
};

const Estrellas: React.FC<{s: number; o: number; y1?: number}> = ({s, o, y1 = 1000}) => (
<g opacity={o}>
{Array.from({length: 46}, (_, i) => <circle key={i} cx={(i * 157) % 1080} cy={(i * 263) % y1} r={1.6 + (i % 3)} fill="#fff8e0" opacity={0.4 + 0.6 * Math.abs(Math.sin(s * 0.8 + i))} />)}
</g>
);

const Pared: React.FC<{c1: string; c2: string; y?: number}> = ({c1, c2, y = 1500}) => (
<g><rect x={-500} y={-300} width={2100} height={y + 300} fill={c1} /><rect x={-500} y={y} width={2100} height={900} fill={c2} /><rect x={-500} y={y} width={2100} height={14} fill="#000" opacity={0.12} /></g>
);

const Trigo: React.FC<{s: number; y?: number; color?: string; n?: number}> = ({s, y = 1500, color = '#e8b84a', n = 22}) => (
<g>
{Array.from({length: n}, (_, i) => {
const x = -60 + i * (1200 / n);
const sw = Math.sin(s * 1.8 + i * 0.6) * 22;
return <g key={i}><path d={`M${x} ${y + 40} Q${x + sw * 0.4} ${y - 90} ${x + sw} ${y - 190 - (i % 3) * 25}`} stroke={color} strokeWidth={6} fill="none" /><ellipse cx={x + sw} cy={y - 200 - (i % 3) * 25} rx={11} ry={30} fill={color} transform={`rotate(${sw * 0.5} ${x + sw} ${y - 200 - (i % 3) * 25})`} /></g>;
})}
</g>
);

const Durmiente: React.FC<{s: number; x: number; y: number; e?: number; piel: string; pelo: string; manta: string; fase?: number}> = ({s, x, y, e = 1, piel, pelo, manta, fase = 0}) => {
const r = Math.sin(s * 1.6 + fase) * 6;
return (
<g transform={`translate(${x} ${y}) scale(${e})`}>
<ellipse cx={-150} cy={-30} rx={84} ry={38} fill="#f4efe6" />
<circle cx={-150} cy={-64} r={46} fill={piel} />
<path d="M-196 -68 Q-196 -114 -150 -112 Q-104 -114 -104 -72 Q-130 -98 -196 -68Z" fill={pelo} />
<path d="M-172 -62 Q-164 -55 -156 -62 M-146 -62 Q-138 -55 -130 -62" stroke="#15110f" strokeWidth={4} fill="none" strokeLinecap="round" />
<ellipse cx={-176} cy={-46} rx={9} ry={6} fill="#ff8a8a" opacity={0.35} />
<path d={`M-112 -40 Q0 ${-104 - r} 182 -52 Q204 0 182 12 L-122 12 Q-132 -10 -112 -40Z`} fill={manta} />
<path d={`M-60 ${-74 - r} Q40 ${-94 - r} 150 -52`} stroke="#fff" strokeOpacity={0.18} strokeWidth={8} fill="none" />
</g>
);
};

const ABUELO: Look = {piel: '#d8a27c', ropa: '#7fa36b', ropa2: '#efe2c8', pelo: '#ece8e0', pant: '#5a4a3a', peinado: 'canoso', lentes: true};
const ABUELA: Look = {piel: '#a8704e', ropa: '#d0607a', ropa2: '#f5d0a0', pelo: '#e6e2da', pant: '#6a4a5a', peinado: 'moño', lentes: true, tunica: true};
const VECINA: Look = {piel: '#8d5a3b', ropa: '#f2b33d', ropa2: '#fff6e0', pelo: '#1e1410', pant: '#3f5f7a', peinado: 'largo'};
const ANGEL: Look = {piel: '#f0c9a0', ropa: '#fff6e2', ropa2: '#f2d48a', pelo: '#e8b860', peinado: 'largo', tunica: true, alas: true};

const Silla: React.FC<{x: number; brillo: number}> = ({x, brillo}) => (
<g><rect x={x} y={1160} width={26} height={340} rx={8} fill="#8a5a3a" /><rect x={x} y={1330} width={150} height={26} rx={8} fill="#8a5a3a" /><rect x={x + 124} y={1340} width={22} height={160} fill="#8a5a3a" />
<rect x={x - 10} y={1150} width={46} height={360} rx={14} fill="#fff1c8" opacity={0.35 * brillo} /></g>
);

export const Escena: React.FC = () => {
const {s} = useS();
const tSi = en('sillas'), tR = en('radio'), tG = en('gracias'), tRi = en('risas'), tPa = en('palabra'), tNi = en('nietos');
const tAm = en('amargura'), tFa = en('familia'), tVi = en('visita'), tOj = en('ojos'), tMa = en('mayor'), tLl = en('llame'), tF = en('nombre');
const suena = ventana(s, -1, tR + 0.3, 0.3);
return (
<AbsoluteFill style={{background: '#f2c88a'}}>
<svg viewBox="0 0 1080 1920" width="100%" height="100%">
<Sitio s={s} t0={-1} t1={tG}>
<g transform={cam(s, [[0, 600, 1200, 1.15], [tSi, 640, 1180, 0.98], [tR, 760, 1160, 1.2]])}>
<Pared c1="#f0c48a" c2="#a8754e" />
<rect x={640} y={560} width={360} height={420} rx={20} fill="#ffe9b8" />
<Rayos s={s} x={820} y={600} color="#fff3d0" k={0.7} n={5} />
<rect x={640} y={560} width={360} height={420} rx={20} fill="none" stroke="#7a5236" strokeWidth={22} />
<Silla x={-40} brillo={ventana(s, tSi, tR, 0.3)} />
<Silla x={760} brillo={ventana(s, tSi + 0.3, tR, 0.3)} />
<Figura id="a1" x={320} y={1640} e={1.4} L={ABUELO} s={s} P={{sen: 1, bi: 70, bd: lerp(s, [0, 1, tR, tR + 0.5], [70, 110, 110, 70]), cab: lerp(s, [0, 1.2, tSi], [10, 18, -4]), boca: 0.2}} />
<rect x={300} y={1310} width={800} height={40} rx={10} fill="#c98b5a" />
<rect x={480} y={1350} width={30} height={170} fill="#a8754e" /><rect x={960} y={1350} width={30} height={170} fill="#a8754e" />
<rect x={470} y={1250} width={60} height={60} rx={10} fill="#e6e0d0" />
{[0, 1, 2].map((i) => <circle key={i} cx={500 + 14 * Math.sin(s * 2 + i)} cy={1230 - ((s * 50 + i * 60) % 180)} r={16} fill="#fff" opacity={0.3} />)}
<rect x={620} y={1278} width={70} height={30} rx={6} fill="#3a3a44" />
<rect x={820} y={1200} width={150} height={110} rx={18} fill="#c0503a" />
<circle cx={860} cy={1255} r={28} fill="#5a2a22" />
{[0, 1, 2].map((i) => <path key={i} d={`M${990 + i * 26} ${1230 - i * 10} q${20} 30 0 60`} stroke="#fff" strokeWidth={6} fill="none" opacity={suena * (0.5 + 0.5 * Math.sin(s * 8 + i))} />)}
</g>
<Polvo s={s} n={22} />
</Sitio>

<Sitio s={s} t0={tG} t1={tAm}>
<g transform={cam(s, [[tG, 540, 1150, 1.05], [tRi, 600, 1050, 1.25], [tPa, 540, 1100, 1], [tNi, 560, 1080, 1.15]])}>
<Pared c1="#f6d9a0" c2="#b98758" />
<rect x={120} y={540} width={840} height={560} rx={24} fill="#a8d4e6" />
<circle cx={760} cy={720} r={110} fill="#fff4c4" />
<Rayos s={s} x={760} y={720} k={0.4 + 0.6 * ap(s, tPa, 1)} />
<rect x={120} y={540} width={840} height={560} rx={24} fill="none" stroke="#7a5236" strokeWidth={26} />
<rect x={100} y={1090} width={880} height={30} fill="#7a5236" />
<Paloma s={s} t0={tPa - 0.5} dur={4} y={800} dir={-1} e={1.1} />
<Figura id="a2" x={460} y={1660} e={1.45} L={ABUELO} s={s} P={{bi: 150, bd: 150, cab: lerp(s, [tG, tRi, tPa], [-6, 6, -12]), boca: lerp(s, [tG, tRi], [0.2, 1])}} />
<g transform={`translate(${460} ${1000}) scale(${1 + 0.15 * ap(s, tRi, 0.6)})`}>
